from __future__ import annotations

import asyncio
import sys
from datetime import UTC, datetime
from pathlib import Path
from typing import Any

# Make the repo root importable when running from a source checkout.
_REPO_ROOT = Path(__file__).resolve().parents[1]
if str(_REPO_ROOT) not in sys.path:
    sys.path.insert(0, str(_REPO_ROOT))

from actor_factory.runner import ActorRunConfig, PPEScraperRunner  # noqa: E402


async def _guarded(coro: Any) -> Any:
    """Await a data call; a failure degrades to None, never kills the run."""
    try:
        return await coro
    except Exception:  # noqa: BLE001 - per-section degradation by design
        return None


class PropsEngineRunner(PPEScraperRunner):
    """Runner that maps one URL to player-prop intelligence items."""

    async def process_url(self, url: str, options: dict[str, Any]) -> dict[str, Any]:
        from datasets.sports_data import player_intel

        sport = options.get("sport", "nba") or "nba"
        team = options.get("team") or ""
        player_name = options.get("player_name") or ""
        include_lineups = options.get("include_lineups", True)
        include_stats = options.get("include_stats", True)
        include_matchup = options.get("include_matchup_context", True)

        item: dict[str, Any] = {
            "url": url,
            "status": "ok",
            "sport": sport,
            "team": team,
            "player_name": player_name,
            "scraped_at": datetime.now(UTC).isoformat(),
        }

        # Live props are the base layer for every run.
        props_res = await _guarded(
            player_intel.get_player_props_live(player_name=player_name, sport=sport)
        )
        props = props_res if isinstance(props_res, list) else []
        item["props"] = props

        if include_lineups and team:
            lineup_res = await _guarded(player_intel.get_lineups(team=team, sport=sport))
            item["lineup_data"] = lineup_res or {}
        else:
            item["lineup_data"] = {}

        if include_stats and player_name:
            stats_res = await _guarded(
                player_intel.get_player_recent_stats(player_name=player_name, sport=sport)
            )
            stats = stats_res or {}
            item["recent_stats"] = stats
            item["streaks"] = stats.get("trend") or stats.get("streaks") or {}
        else:
            item["recent_stats"] = {}
            item["streaks"] = {}

        if include_matchup and team:
            # Matchup context needs both sides; degrade gracefully when only
            # one team is known by using the team for both home and away.
            matchup_res = await _guarded(
                player_intel.get_props_vs_matchup(home_team=team, away_team=team, sport=sport)
            )
            item["defensive_context"] = matchup_res or {}
        else:
            item["defensive_context"] = {}

        item["metadata"] = {
            "domain": url.split("/")[2] if "://" in url else url,
            "sport": sport,
            "team": team,
            "player_name": player_name,
            "prop_count": len(props),
        }
        return item


async def main() -> None:
    runner = PropsEngineRunner(
        config=ActorRunConfig(
            primary_event="props-pulled",
            default_output_format="markdown",
            processor_name="jsondata",
        ),
        actor_module=None,  # resolved lazily so tests can inject a mock
    )
    await runner.run()


if __name__ == "__main__":
    asyncio.run(main())
